const sd = $getWorkflowStaticData('global');
const agora = Math.floor(Date.now() / 1000);
return [{ json: { desde: sd.cursor ? sd.cursor : agora - 86400 } }];

const r = $input.first().json || {};
if (!Array.isArray(r.notas) || r.notas.length === 0) return [];
return r.notas.map(n => ({ json: Object.assign({}, n, { q: encodeURIComponent(n.id) }) }));

const sd = $getWorkflowStaticData('global');
sd.hashes = sd.hashes || {};
const lista = $('Lista').all().map(i => i.json);
function h53(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
const out = [];
let livre = null;
let achou = false;
$input.all().forEach((r, i) => {
  const n = lista[i];
  const j = r.json || {};
  const texto = String(j.texto || '').trim();
  const titulo = String(j.titulo || n.titulo || '').trim();
  const hash = h53(titulo + '\n' + texto, 1);
  // Só os espelhos do próprio Second Brain ficam de fora (evita laço); todas as outras notas, inclusive as geradas pelo Heimdall, entram.
  const doHeimdall = /^(C[ée]rebro: |Second Brain: )/.test(titulo) || /^---\s*\ntitulo: .*\norigem: apple-notes/.test(texto);
  if (j.erro || doHeimdall || texto.length < 80 || sd.hashes[n.id] === hash) { if (!achou) livre = n.mod; return; }
  achou = true;
  out.push({ json: { id: n.id, pasta: n.pasta, titulo, texto: texto.slice(0, 6000), hash, mod: n.mod, nova: !sd.hashes[n.id] } });
});
if (livre !== null) sd.cursor = Math.max(sd.cursor || 0, livre);
return out;

const base = $('Preparar').all();
return $input.all()
  .map((r, i) => {
    const v = (((r.json || {}).embeddings) || [])[0];
    return { json: Object.assign({}, base[i].json, { vetor: Array.isArray(v) ? v : null }) };
  })
  .filter(x => x.json.vetor);

const base = $('Juntar vetor').all();
const SYS = 'Você é o gestor de conhecimento pessoal de um profissional de dados. Analise a nota e compare com notas parecidas da base. Escreva em português do Brasil. Não invente informações que não estejam nas notas.';
return $input.all().map((r, i) => {
  const b = base[i].json;
  const pts = ((((r.json || {}).result) || {}).points || [])
    .filter(p => p.payload && p.payload.note_id !== b.id && (p.score || 0) >= 0.5)
    .slice(0, 5);
  const viz = pts.map((p, k) => ({ ref: 'V' + (k + 1), titulo: String(p.payload.titulo || ''), trecho: String(p.payload.trecho || '').slice(0, 240) }));
  const lista = viz.length ? viz.map(v => v.ref + ': ' + v.titulo + ' - ' + v.trecho).join('\n') : '(nenhuma nota parecida encontrada)';
  const user = 'NOTA ATUAL\nTítulo: ' + b.titulo + '\n' + b.texto + '\n\nNOTAS PARECIDAS NA BASE\n' + lista
    + '\n\nResponda somente com um objeto JSON com as chaves: resumo (uma ou duas frases); tags (3 a 7 tags semânticas em minúsculas, sem espaços, com hífen); conceitos (3 a 6 conceitos-chave); entidades (pessoas, organizações, produtos e lugares citados); conexoes (lista de objetos com ref, tipo e motivo, onde ref é V1, V2 e assim por diante, tipo é complementa, contradiz, relacionada ou duplica, e motivo é uma frase; inclua só conexões reais e só refs da lista); lacunas (2 a 4 pontos que a nota não cobre e que merecem aprofundamento); perguntas (1 a 3 perguntas para estudar depois).';
  return { json: Object.assign({}, b, { viz, req: { model: '__MODELO__', temperature: 0.2, max_tokens: 1300, stream: false,
    response_format: { type: 'json_object' }, messages: [ { role: 'system', content: SYS }, { role: 'user', content: user } ] } }) };
});

const base = $('Montar análise').all();
const sem = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const arr = x => (Array.isArray(x) ? x.map(v => String(v).trim()).filter(Boolean) : []);
const q = s => JSON.stringify(String(s));
const TIPOS = ['complementa', 'contradiz', 'relacionada', 'duplica'];
const out = [];
$input.all().forEach((r, i) => {
  const b = base[i].json;
  const txt = String(((((r.json || {}).choices || [])[0] || {}).message || {}).content || '');
  let a = {};
  try { a = JSON.parse(txt); } catch (e) {
    const m = /\{[\s\S]*\}/.exec(txt);
    try { a = m ? JSON.parse(m[0]) : {}; } catch (e2) { a = {}; }
  }
  let tags = Array.from(new Set(arr(a.tags).map(sem).filter(Boolean))).slice(0, 7);
  const resumo = String(a.resumo || '').trim();
  if (tags.length === 0 && !resumo) return;
  const conceitos = arr(a.conceitos).slice(0, 6);
  const entidades = arr(a.entidades).slice(0, 10);
  if (!tags.length) tags = Array.from(new Set(entidades.map(sem).filter(Boolean))).slice(0, 5);
  const lacunas = arr(a.lacunas).slice(0, 4);
  const perguntas = arr(a.perguntas).slice(0, 3);
  const conexoes = (Array.isArray(a.conexoes) ? a.conexoes : []).map(c => {
    const v = b.viz.find(x => x.ref === String(c.ref));
    return v ? { titulo: v.titulo, tipo: TIPOS.includes(String(c.tipo)) ? String(c.tipo) : 'relacionada', motivo: String(c.motivo || '').trim() } : null;
  }).filter(Boolean);
  const fm = ['---', 'titulo: ' + q(b.titulo), 'origem: apple-notes', 'pasta: ' + q(b.pasta), 'nota_id: ' + q(b.id),
    'tags: [' + tags.join(', ') + ']', 'conceitos: [' + conceitos.map(q).join(', ') + ']',
    'entidades: [' + entidades.map(q).join(', ') + ']', 'atualizado: ' + new Date().toISOString(), '---', ''];
  const corpo = ['## Resumo', resumo || '(sem resumo)', '', '## Conexões sugeridas'];
  if (conexoes.length) conexoes.forEach(c => corpo.push('- [[' + c.titulo + ']] (' + c.tipo + '): ' + c.motivo));
  else corpo.push('- Nenhuma conexão clara com as notas existentes.');
  corpo.push('', '## Lacunas e pontos a aprofundar');
  if (lacunas.length) lacunas.forEach(l => corpo.push('- ' + l)); else corpo.push('- Nenhuma lacuna evidente.');
  if (perguntas.length) { corpo.push('', '## Perguntas para estudar'); perguntas.forEach(p => corpo.push('- ' + p)); }
  corpo.push('', 'Nota original: ' + b.titulo);
  const analise = { nota_id: b.id, titulo: b.titulo, pasta: b.pasta, resumo, tags, conceitos, entidades, conexoes, lacunas, perguntas };
  out.push({ json: { analise, id: b.id, hash: b.hash, mod: b.mod, titulo: b.titulo, pasta: b.pasta, tags, vetor: b.vetor,
    trecho: b.texto.slice(0, 500), contradicoes: conexoes.filter(c => c.tipo === 'contradiz'),
    espelho: { pasta: 'Second Brain', titulo: ('Second Brain: ' + b.titulo).slice(0, 190), markdown: fm.concat(corpo).join('\n') } } });
});
return out;

const esp = $('Montar espelho').all();
function h53(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
return esp.map(x => {
  const e = x.json;
  const hex = (h53(e.id, 1) + h53(e.id, 2) + h53(e.id, 3)).replace(/[^0-9a-f]/g, '').padEnd(32, '0').slice(0, 32);
  const uuid = hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-' + hex.slice(12, 16) + '-' + hex.slice(16, 20) + '-' + hex.slice(20, 32);
  return { json: { ponto: { id: uuid, vector: e.vetor, payload: { note_id: e.id, titulo: e.titulo, pasta: e.pasta, trecho: e.trecho,
    tags: e.tags, atualizado: new Date().toISOString() } } } };
});

const sd = $getWorkflowStaticData('global');
sd.hashes = sd.hashes || {};
const esp = $('Montar espelho').all().map(i => i.json);
const gr = $('Gravar espelho').all();
let falhas = 0;
const contr = [];
esp.forEach((e, i) => {
  sd.hashes[e.id] = e.hash;
  if (!gr[i] || !gr[i].json || gr[i].json.ok !== true) falhas++;
  (e.contradicoes || []).forEach(c => contr.push(e.titulo + ' x ' + c.titulo + ': ' + c.motivo));
});
const maxMod = Math.max.apply(null, $('Lista').all().map(i => i.json.mod));
if (isFinite(maxMod)) sd.cursor = Math.max(sd.cursor || 0, maxMod);
const msgs = [];
if (contr.length) msgs.push('Possível contradição entre notas:\n' + contr.join('\n'));
if (falhas) msgs.push('Não consegui gravar ' + falhas + ' nota(s) espelho no app Notas. Confira o agente do Mac (heimdall_agente.py).');
if (!msgs.length) return [];
return [{ json: { titulo: contr.length ? 'Second Brain: possível contradição' : 'Second Brain: atenção', corpo: msgs.join('\n\n') } }];
